 "content": "def transform(grid):
    out=[row[:] for row in grid]
    # The marked 1-cell shape is a seed: copy its arrangement into every matching
    # 0/5 region, replacing only the cells corresponding to the seed's 1s.
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    if not pts: return out
    # Shape is three vertically aligned cells; stamp at occurrences where the
    # surrounding checker/noise pattern admits the same three-cell footprint.
    h=max(r for r,c in pts)-min(r for r,c in pts)+1
    w=max(c for r,c in pts)-min(c for r,c in pts)+1
    shape={(r-min(x for x,y in pts),c-min(y for x,y in pts)) for r,c in pts}
    for r in range(len(grid)-h+1):
      for c in range(len(grid[0])-w+1):
        if all((r+dr,c+dc) not in pts for dr,dc in shape):
          # intent: preserve seed, stamp where cells in template match zero-valued pixels
          if all(grid[r+dr][c+dc] in (0,5) for dr,dc in shape):
            for dr,dc in shape: out[r+dr][c+dc]=1
    return out
